181	  void load_elf(const std::string& path)
182	  {
183	    const auto elf = LIEF::ELF::Parser::parse(path);
184	    if (!elf) {
185	      spdlog::critical("Check if it's a valid ELF file path : {}", path);
186	      exit(1);
187	    }
188	
189	    read_elf_into_memory(*elf, xlen_t{0}, platform.main_memory.data);
190	    for (auto& rv: platform.reset_vector)
191	      rv.write(elf->entrypoint());
192	  }
