194	  void set_reset_vector(size_t hart, uint64_t addr)
195	  {
196	    if (hart >= platform.reset_vector.size()) {
197	      spdlog::critical("hart {} out of range (max {})", hart,
198	                       platform.reset_vector.size() - 1);
199	      std::exit(EXIT_FAILURE);
200	    }
201	    platform.reset_vector[hart].write(addr);
202	  }
203	
204	  void load_image(const std::string& path, MEM_TYPE type)
205	  {
206	    switch (type) {
207	    case MEM_TYPE::ILM:
208	      if constexpr (requires { cpu.set_ilm({}); }) {
209	        read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
210	      } else {
211	        throw std::runtime_error(
212	          "CPU does not support ILM - cannot load ILM ROM image");
213	      }
214	      break;
215	
216	    case MEM_TYPE::DLM:
217	      if constexpr (requires { cpu.set_dlm({}); }) {
218	        read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
219	      } else {
220	        throw std::runtime_error(
221	          "CPU does not support DLM - cannot load DLM ROM image");
222	      }
223	      break;
224	
225	    case MEM_TYPE::RAM:
226	      read_binary_file(path, [this](const auto& data) {
227	        if (data.size() > platform.main_memory.data.size())
228	          throw std::runtime_error("RAM image size exceeds main memory size");
229	        std::copy(data.begin(), data.end(), platform.main_memory.data.begin());
230	      });
231	      break;
232	
233	    default:
234	      throw std::runtime_error("Unknown memory type");
235	    }
236	  }
