238	  void reset()
239	  {
240	    static constexpr int core_num = CPU::NDS_NHART;
241	    static constexpr int reset_val = (1 << core_num) - 1;
242	
243	    platform.resetn.write(0);
244	    auto saved = context_config;
245	    context_config = {};
246	    this->run(1);
247	    context_config = saved;
248	
249	    for (size_t i = 0; i < platform.reset_vector.size(); ++i)
250	      spdlog::info("hart {} reset vector: {:#x}", i,
251	                   (uint64_t) platform.reset_vector[i].read());
252	
253	    platform.resetn.write(reset_val);
254	
255	    if (context_config.continue_from)
256	      restore_context(context_config.dir);
257	  }
258	
259	  int run(const uint64_t max_cycles = std::numeric_limits<uint64_t>::max())
260	  {
261	    auto sa = memzeroed<struct sigaction>();
262	    sa.sa_handler = sigint_handler;
263	    sigemptyset(&sa.sa_mask);
264	
265	    auto oact = memzeroed<struct sigaction>();
266	    if (sigaction(SIGINT, &sa, &oact) == -1)
267	      perror("sigaction");
268	
269	    const auto restore_sigint = std::experimental::scope_exit{[&] {
270	      if (sigaction(SIGINT, &oact, nullptr) == -1)
271	        perror("sigaction");
272	    }};
273	
274	    // wait for debugger connections
275	    while (dtm_debug && !dtm.is_connected()) {
276	      dtm.try_accept_socket();
277	      if (ctrlc != 0) {
278	        return 130;
279	      }
280	      sleep(1);
281	    }
282	
283	    [[maybe_unused]]
284	    bool ctx_resuming = context_config.continue_from;
285	    [[maybe_unused]]
286	    bool ctx_triggered = false;
287	
288	    for (auto n = uint64_t{0}; n < max_cycles; ++n) {
289	
290	      if (ctx_resuming) [[unlikely]] {
291	        // Pull up PLIC interrupt signal at the first cycle of the resume
292	        platform.int_trigger.write(1);
293	        ctx_resuming = false;
294	        ctx_triggered = true;
295	      }
296	
297	      sc_core::sc_start(platform.clk.period());
298	
299	      trace_.on_cycle(cpu);
300	
301	      if (context_config.save_on_wfi && platform.wfi_signal.read() == true)
302	        [[unlikely]]
303	      {
304	        context_config.save(platform, cpu);
305	        spdlog::info("User save context");
306	        return 0;
307	      }
308	
309	      if (ctrlc != 0) {
310	        ctrlc = 0;
311	        spdlog::info("Ctrl+C PC: {:x}", get_current_pc());
312	        trace_.log_committed_pcs(cpu);
313	        return 130;
314	      }
315	
316	      if (ctx_triggered) [[unlikely]] {
317	        // Pull down the interrupt signal after 1 cycle
318	        platform.int_trigger.write(0);
319	        ctx_triggered = false;
320	      }
321	
322	      if (platform.sim_control.exits >= 0) {
323	        spdlog::info("sim_control: got exit {}, stopping",
324	                     platform.sim_control.exits);
325	        spdlog::info("Exit PC: {:x}", get_current_pc());
326	        trace_.log_committed_pcs(cpu);
327	        return platform.sim_control.exits;
328	      }
329	
330	      if (this->cpu.contextp()->gotFinish())
331	        return 0;
332	
333	      spdlog::trace("PC: {:x}", get_current_pc());
334	    }
335	    return 0;
336	  }
337	
338	  uint64_t get_current_pc()
339	  {
340	    if constexpr (requires { cpu.get_current_pc(); }) {
341	      return cpu.get_current_pc();
342	    }
343	    return std::numeric_limits<uint64_t>::max();
344	  }
