200	 200   // Caller invariant: the CPU must already be out of reset.
201	 201   //
202	 202   // baseline_cache (LG3): path to this (engine build, ELF)'s reset-state
203	 203   // baseline; empty disables the liveness gate (transport-everything). On a
204	 204   // cache miss the baseline is captured HERE: the hart is freshly reset and
205	 205   // the capture drain halts it exactly where resume() would, so the drained
206	 206   // values ARE what the gate must compare restores against. Capture runs
207	 207   // BEFORE the scratch stagings below -- its drain sweeps dump reset
208	 208   // registers through the same scratch page the stagings fill.
209	 209   void apply_resume_from_qemu(const std::string& path,
210	 210                               const std::string& baseline_cache = {})
211	 211   {
212	 212     hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
213	 213       bus{platform.dmi, platform.clk.period()};
214	 214     hybrid_input_state_ = hybrid::load_state(path);
215	 215 
216	 216     std::optional<hybrid_state_v1> baseline{};
217	 217     bool baseline_captured = false;
218	 218     if (!baseline_cache.empty()) {
219	 219       baseline = hybrid::try_load_reset_baseline(baseline_cache);
220	 220       // Stale-shape insurance: a cache whose flags/vlenb no longer cover the
221	 221       // incoming state was captured under a different engine/QEMU pairing.
222	 222       if (baseline
223	 223           && ((baseline->flags & hybrid_input_state_->flags)
224	 224                 != hybrid_input_state_->flags
225	 225               || baseline->vlenb != hybrid_input_state_->vlenb))
226	 226         baseline.reset();
227	 227       if (!baseline) {
228	 228         baseline = capture_reset_baseline(bus, *hybrid_input_state_);
229	 229         baseline_captured = true;
230	 230         if (!hybrid::save_reset_baseline(baseline_cache, *baseline))
231	 231           spdlog::warn("hybrid: cannot save reset baseline to {}",
232	 232                        baseline_cache);
233	 233       }
234	 234       spdlog::info("hybrid: reset baseline {} ({})",
235	 235                    baseline_captured
236	 236                      ? "captured -- one-time cost per engine build + ELF"
237	 237                      : "cache hit",
238	 238                    baseline_cache);
239	 239     }
240	 240 
241	 241     // Stage V-register bytes into the fixed scratch region of RAM BEFORE
242	 242     // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
243	 243     // this region to repopulate v0..v31, so the bytes must be in place first.
244	 244     // Best-effort: mismatched RAM layouts throw, which is louder than silently
245	 245     // dropping V state.
246	 246     if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
247	 247       hybrid::stage_v_to_scratch(*hybrid_input_state_,
248	 248                                  platform.main_memory.data);
249	 249     }
250	 250     // GPR/FPR/CSR transport is Abstract-Command-only in BOTH directions (never
251	 251     // Program Buffer): a csrrw to a caps-supported but read-only / WARL-illegal
252	 252     // CSR raises cmderr, and the abstract path's per-CSR clear_cmderr tolerates
253	 253     // that single failure and moves on -- a batched PB sweep could not. The
254	 254     // Program Buffer carries only what abstract commands cannot reach: the V
255	 255     // data sweep, the Tier-B vsetvl, and the L2C MMIO window.
256	 256     const auto caps = active_caps();
257	 257     hybrid::ResumeDriver driver(bus, v_scratch_gpa(), caps);
258	 258     driver.set_l2c(l2c_present(), l2c_base());  // v5: restore L2C config if present
259	 259     // LG3: on a capture run the capture drain's V dump sweep clobbered
260	 260     // vtype/vl/vstart, so the vsetvl elision is only valid on cache hits.
261	 261     if (baseline)
262	 262       driver.set_reset_baseline(*baseline,
263	 263                                 /*v_cfg_at_reset=*/!baseline_captured);
264	 264     std::size_t andes_mext_csrs = 0;
265	 265     hybrid::for_each_transport_csr(*hybrid_input_state_, caps,
266	 266       [&](uint16_t, const uint64_t&) { ++andes_mext_csrs; });
267	 267     const auto resume_t0 = sc_core::sc_time_stamp();
268	 268     const auto wall_t0 = std::chrono::steady_clock::now();
269	 269     driver.resume(*hybrid_input_state_);
270	 270     const auto wall_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
271	 271       std::chrono::steady_clock::now() - wall_t0).count();
272	 272     const auto resume_cycles = static_cast<uint64_t>(
273	 273       (sc_core::sc_time_stamp() - resume_t0) / platform.clk.period());
274	 274     spdlog::info("hybrid: resume={} cycles ({} ms wall), restore path="
275	 275                  "abstract, andes+m-ext csrs={}",
276	 276                  resume_cycles, wall_ms, andes_mext_csrs);
277	 277     if (baseline)
278	 278       spdlog::info("hybrid: liveness gate elided {} register restores",
279	 279                    driver.baseline_skip_count());
280	 280   }
281	 281 
282	 282   // F3: standalone CSR existence + reset-value probe. Halts the freshly-reset
283	 283   // hart via DMI and checked-reads each address -- cmderr (an unimplemented
284	 284   // CSR) surfaces as nullopt. No QEMU state, no run(): the read values ARE the
285	 285   // architectural reset state. Emitted by `--probe`, consumed by andesim's
286	 286   // gen_manifest.py to MEASURE the implemented set + reset values instead of
287	 287   // hand-tracing RTL params. The caller must load a (spin) ELF first so the
288	 288   // reset vector is mapped -- the hart fetches a couple instructions from it
289	 289   // before the DMI halt takes effect (same window capture_reset_baseline uses).
290	 290   auto probe_csrs(const std::vector<uint16_t>& addrs)
291	 291     -> std::vector<std::pair<uint16_t, std::optional<uint64_t>>>
292	 292   {
293	 293     using RD = hybrid::ResumeDriver;
294	 294     hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
295	 295       bus{platform.dmi, platform.clk.period()};
296	 296     bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
297	 297     bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
298	 298     hybrid::poll_until_set(bus, RD::kDmstatus, RD::kDmstatusAllhalted,
299	 299                            "csr-probe halt");
300	 300     // At reset mstatus.FS/VS are Off, so FP/V CSR reads raise illegal-insn
301	 301     // (cmderr) and would mis-probe as absent. Enable them (WARL no-op on an
302	 302     // engine without FP/V), exactly like capture_reset_baseline before its
303	 303     // FP/V reads. mstatus's own probed value is thus FS/VS-perturbed -- a known
304	 304     // artifact (mstatus is a base always-transported, verify-excluded CSR).
305	 305     {
306	 306       const uint64_t mstatus = hybrid::read_register_64(
307	 307         bus, hybrid::regno_csr(RD::kCsrMstatus), "csr-probe mstatus");
308	 308       uint64_t enable = mstatus;
309	 309       if ((enable & RD::kMstatusFsMask) == 0) enable |= RD::kMstatusFsInitial;
310	 310       if ((enable & RD::kMstatusVsMask) == 0) enable |= RD::kMstatusVsInitial;
311	 311       if (enable != mstatus)
312	 312         hybrid::write_register_abstract(
313	 313           bus, hybrid::regno_csr(RD::kCsrMstatus), enable);
314	 314     }
315	 315     std::vector<std::pair<uint16_t, std::optional<uint64_t>>> out;
316	 316     out.reserve(addrs.size());
317	 317     for (const uint16_t a: addrs)
318	 318       out.emplace_back(a, hybrid::read_register_64_checked(
319	 319                             bus, hybrid::regno_csr(a), "csr-probe"));
320	 320     return out;
321	 321   }
322	 322 
323	 323   // Enables the vsim->QEMU handoff drain. After this is set, run() watches
324	 324   // committed PCs and on retire of a `csrw 0x7C0, *` exit-trigger drains
325	 325   // architectural state to `state_out_path` and returns kExitHandoffToQemu.
326	 326   //
327	 327   // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
328	 328   // mode) and the ELF scan is skipped: the binary need not contain a magic
329	 329   // csrwi marker. CSR mode and PC mode are mutually exclusive on a single
330	 330   // run -- callers pass exactly one form.
331	 331   void enable_hybrid_handoff(const std::string& elf_path,
332	 332                              const std::string& state_out_path,
333	 333                              std::optional<uint64_t> exit_pc = std::nullopt,
334	 334                              bool drain_minimal = false)
335	 335   {
336	 336     hybrid::CsrTrigger trigger;
337	 337     if (exit_pc) {
338	 338       trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
339	 339       spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
340	 340     } else {
341	 341       auto elf = LIEF::ELF::Parser::parse(elf_path);
342	 342       if (!elf)
343	 343         throw std::runtime_error(
344	 344           "enable_hybrid_handoff: failed to parse " + elf_path);
345	 345       for (const auto& seg: elf->segments()) {
346	 346         if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
347	 347         if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
348	 348         const auto content = seg.content();
349	 349         const std::span<const uint8_t> bytes{content.data(), content.size()};
350	 350         trigger.scan_buffer(bytes, seg.virtual_address());
351	 351       }
352	 352     }
353	 353 
354	 354     hybrid_dmi_bus_ = std::make_unique<
355	 355       hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
356	 356                             PLATFORM::dmi_data_width>>(platform.dmi,
357	 357                                                        platform.clk.period());
358	 358     hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
359	 359                             v_scratch_gpa(), active_caps());
360	 360     if (hybrid_input_state_)
361	 361       hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
362	 362     hybrid_handoff_->set_minimal_drain(drain_minimal);
363	 363     hybrid_handoff_->set_l2c(l2c_present(), l2c_base());  // v5: exit drain re-reads L2C
364	 364 
365	 365     hybrid_state_path_ = state_out_path;
366	 366   }
367	 367 
368	 368   // F6: override the config-derived caps with a manifest-driven transport set
369	 369   // (from --transport-csrs). When set, active_caps() returns this instead of
370	 370   // andes_caps_from_config() -- the runtime transport is then driven by the
371	 371   // registered manifest, not by re-modelling config macros.
372	 372   void set_transport_caps(const hybrid::AndesCaps& c) { transport_caps_ = c; }
373	 373 
374	 374 private:
375	 375   std::optional<hybrid::AndesCaps> transport_caps_{};
376	 376   auto active_caps() const -> hybrid::AndesCaps
377	 377   {
378	 378     return transport_caps_ ? *transport_caps_ : hybrid::andes_caps_from_config();
379	 379   }
380	 380 
381	 381   // v5: L2C MMIO transport gate, derived from the build's Verilog config macros
382	 382   // (_NDS_*, supplied via cpu_config.hpp -- same source as andes_caps_from_
383	 383   // config). Present only when this engine is built with an L2 cache controller
384	 384   // AND its register base is known. Gated on _NDS_L2C_CACHE_SIZE_KB, not the
385	 385   // cluster's has_shared_cache, because that flag also covers L3 (ax46/ax66).
386	 386   // A store to an absent L2C region would fault the Program Buffer, so this
387	 387   // stays off on every current engine (_NDS_L2C_CACHE_SIZE_KB == 0).
388	 388   static constexpr bool l2c_present()
389	 389   {
390	 390 #if defined(_NDS_L2C_CACHE_SIZE_KB) && defined(_NDS_L2C_REG_BASE)
391	 391     return (_NDS_L2C_CACHE_SIZE_KB) > 0;
392	 392 #else
393	 393     return false;
394	 394 #endif
395	 395   }
396	 396   static constexpr uint64_t l2c_base()
397	 397   {
398	 398 #if defined(_NDS_L2C_REG_BASE)
399	 399     return static_cast<uint64_t>(_NDS_L2C_REG_BASE);
400	 400 #else
401	 401     return 0;
402	 402 #endif
403	 403   }
404	 404 
405	 405   // L26: the GUEST address of the V-register transport page -- the top page of
406	 406   // the mapped RAM span. The driver maps one page above --mem-size (scheme D),
407	 407   // so this sits just past the program's declared RAM and never collides with
408	 408   // its data/stack. Single source of truth handed to ResumeDriver/StateDrain.
409	 409   auto v_scratch_gpa() const -> uint64_t
410	 410   {
411	 411     return hybrid::v_scratch_gpa(platform.main_memory.region.base_address,
412	 412                                  platform.main_memory.data.size());
413	 413   }
414	 414 
415	 415   // LG3: drain the freshly reset, just-halted hart into a baseline the
416	 416   // liveness gate compares restores against. The probe carries the incoming
417	 417   // state's flags/vlenb so drain_with_passthrough reads exactly the blocks
418	 418   // the gate will compare (it is flag-driven); every probe field it does not
419	 419   // re-read stays zero, matching what an absent block compares against.
420	 420   auto capture_reset_baseline(
421	 421     hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
422	 422                           PLATFORM::dmi_data_width>& bus,
423	 423     const hybrid_state_v1& input) -> hybrid_state_v1
424	 424   {
425	 425     hybrid::StateDrain drain(bus, v_scratch_gpa(),
426	 426                              active_caps());
427	 427     // At reset mstatus.FS/VS are Off, so the capture's vse8 sweep (and the
428	 428     // FPR/V CSR abstract reads) would raise illegal instruction (cmderr=3).
429	 429     // Halt and enable them first, exactly like resume() does before its FPR/V
430	 430     // writes. Safe to clobber: mstatus is never re-read by a drain nor gated
431	 431     // by the baseline, and resume() rewrites it whenever the FP/V flags are
432	 432     // set -- the only case this branch runs.
433	 433     if (input.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
434	 434       using RD = hybrid::ResumeDriver;
435	 435       bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
436	 436       bus.write(RD::kDmcontrol,
437	 437                 RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
438	 438       hybrid::poll_until_set(bus, RD::kDmstatus, RD::kDmstatusAllhalted,
439	 439                              "reset-baseline capture halt");
440	 440       const uint64_t mstatus = hybrid::read_register_64(
441	 441         bus, hybrid::regno_csr(RD::kCsrMstatus), "reset-baseline mstatus");
442	 442       uint64_t enable = mstatus;
443	 443       if ((input.flags & HYBRID_FLAG_FP)
444	 444           && (enable & RD::kMstatusFsMask) == 0)
445	 445         enable |= RD::kMstatusFsInitial;
446	 446       if ((input.flags & HYBRID_FLAG_V)
447	 447           && (enable & RD::kMstatusVsMask) == 0)
448	 448         enable |= RD::kMstatusVsInitial;
449	 449       if (enable != mstatus)
450	 450         hybrid::write_register_abstract(
451	 451           bus, hybrid::regno_csr(RD::kCsrMstatus), enable);
452	 452     }
453	 453     hybrid_state_v1 probe{};
454	 454     probe.magic = HYBRID_STATE_MAGIC;
455	 455     probe.version = HYBRID_STATE_VERSION;
456	 456     probe.flags = input.flags;
457	 457     probe.vlenb = input.vlenb;
458	 458     auto baseline = drain.drain_with_passthrough(probe);
459	 459     lift_scratch_blocks(baseline);
460	 460     return baseline;
461	 461   }
462	 462 
463	 463   // Lift the scratch-page transport into `state` (dual of the resume
464	 464   // staging): the V dump sweep bytes back into state.vreg[] -- so the drained
465	 465   // state carries vsim's actual V values, not QEMU 1's stale snapshot. The V
466	 466   // regfile is the only state that rides the scratch page; GPRs, FPRs, and
467	 467   // every CSR drain via abstract reads directly into the state. Shared by the
468	 468   // exit drain and the reset-baseline capture.
469	 469   void lift_scratch_blocks(hybrid_state_v1& state)
470	 470   {
471	 471     const std::span<const uint8_t> ram{platform.main_memory.data.data(),
472	 472                                        platform.main_memory.data.size()};
473	 473     if ((state.flags & HYBRID_FLAG_V) != 0u)
474	 474       hybrid::read_v_from_scratch(state, ram);
475	 475   }
