491	 491   // skip_memory_load: parse the ELF and set the reset vector, but leave
492	 492   // platform.main_memory untouched. Used in tier-2 hybrid resume where
493	 493   // QEMU 1's -kernel already populated the shared mmap; re-loading would
494	 494   // zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
495	 495   // to static buffers. The reset vector is still set so the hart has a
496	 496   // valid fetch target during the post-reset cycles that precede the DMI
497	 497   // halt+DPC-write resume sequence.
498	 498   void load_elf(const std::string& path, bool skip_memory_load = false)
499	 499   {
500	 500     const auto elf = LIEF::ELF::Parser::parse(path);
501	 501     if (!elf) {
502	 502       spdlog::critical("Check if it's a valid ELF file path : {}", path);
503	 503       exit(1);
504	 504     }
505	 505 
506	 506     if (!skip_memory_load)
507	 507       read_elf_into_memory(
508	 508         *elf,
509	 509         static_cast<xlen_t>(platform.main_memory.region.base_address),
510	 510         platform.main_memory.data);
511	 511     for (auto& rv: platform.reset_vector)
512	 512       rv.write(elf->entrypoint());
513	 513   }
