515	 515   void set_reset_vector(size_t hart, uint64_t addr)
516	 516   {
517	 517     if (hart >= platform.reset_vector.size()) {
518	 518       spdlog::critical("hart {} out of range (max {})", hart,
519	 519                        platform.reset_vector.size() - 1);
520	 520       std::exit(EXIT_FAILURE);
521	 521     }
522	 522     platform.reset_vector[hart].write(addr);
523	 523   }
