525	 525   void load_image(const std::string& path, MEM_TYPE type)
526	 526   {
527	 527     switch (type) {
528	 528     case MEM_TYPE::ILM:
529	 529       if constexpr (requires { cpu.set_ilm({}); }) {
530	 530         read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
531	 531       } else {
532	 532         throw std::runtime_error(
533	 533           "CPU does not support ILM - cannot load ILM ROM image");
534	 534       }
535	 535       break;
536	 536 
537	 537     case MEM_TYPE::DLM:
538	 538       if constexpr (requires { cpu.set_dlm({}); }) {
539	 539         read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
540	 540       } else {
541	 541         throw std::runtime_error(
542	 542           "CPU does not support DLM - cannot load DLM ROM image");
543	 543       }
544	 544       break;
545	 545 
546	 546     case MEM_TYPE::RAM:
547	 547       read_binary_file(path, [this](const auto& data) {
548	 548         if (data.size() > platform.main_memory.data.size())
549	 549           throw std::runtime_error("RAM image size exceeds main memory size");
550	 550         std::copy(data.begin(), data.end(), platform.main_memory.data.begin());
551	 551       });
552	 552       break;
553	 553 
554	 554     default:
555	 555       throw std::runtime_error("Unknown memory type");
556	 556     }
557	 557   }
