559	 559   void reset()
560	 560   {
561	 561     static constexpr int core_num = CPU::NDS_NHART;
562	 562     static constexpr int reset_val = (1 << core_num) - 1;
563	 563 
564	 564     platform.resetn.write(0);
565	 565     auto saved = context_config;
566	 566     context_config = {};
567	 567     this->run(1);
568	 568     context_config = saved;
569	 569 
570	 570     for (size_t i = 0; i < platform.reset_vector.size(); ++i)
571	 571       spdlog::info("hart {} reset vector: {:#x}", i,
572	 572                    (uint64_t) platform.reset_vector[i].read());
573	 573 
574	 574     platform.resetn.write(reset_val);
575	 575 
576	 576     if (context_config.continue_from)
577	 577       restore_context(context_config.dir);
578	 578   }
579	 579 
580	 580   int run(const uint64_t max_cycles = std::numeric_limits<uint64_t>::max())
581	 581   {
582	 582     auto sa = memzeroed<struct sigaction>();
583	 583     sa.sa_handler = sigint_handler;
584	 584     sigemptyset(&sa.sa_mask);
585	 585 
586	 586     auto oact = memzeroed<struct sigaction>();
587	 587     if (sigaction(SIGINT, &sa, &oact) == -1)
588	 588       perror("sigaction");
589	 589 
590	 590     const auto restore_sigint = std::experimental::scope_exit{[&] {
591	 591       if (sigaction(SIGINT, &oact, nullptr) == -1)
592	 592         perror("sigaction");
593	 593     }};
594	 594 
595	 595     // wait for debugger connections
596	 596     while (dtm_debug && !dtm.is_connected()) {
597	 597       dtm.try_accept_socket();
598	 598       if (ctrlc != 0) {
599	 599         return 130;
600	 600       }
601	 601       sleep(1);
602	 602     }
603	 603 
604	 604     [[maybe_unused]]
605	 605     bool ctx_resuming = context_config.continue_from;
606	 606     [[maybe_unused]]
607	 607     bool ctx_triggered = false;
608	 608 
609	 609     for (auto n = uint64_t{0}; n < max_cycles; ++n) {
610	 610 
611	 611       if (ctx_resuming) [[unlikely]] {
612	 612         // Pull up PLIC interrupt signal at the first cycle of the resume
613	 613         platform.int_trigger.write(1);
614	 614         ctx_resuming = false;
615	 615         ctx_triggered = true;
616	 616       }
617	 617 
618	 618       sc_core::sc_start(platform.clk.period());
619	 619 
620	 620       trace_.on_cycle(cpu);
621	 621 
622	 622       if (hybrid_handoff_) [[unlikely]] {
623	 623         if (auto code = check_hybrid_handoff(); code) return *code;
624	 624       }
625	 625 
626	 626       if (context_config.save_on_wfi && platform.wfi_signal.read() == true)
627	 627         [[unlikely]]
