23	class HandoffController
24	{
25	public:
26	  HandoffController(Trigger trigger, DmiBus& bus)
27	      : trigger_{std::move(trigger)}, drain_{bus}
28	  {}
29	
30	  // Snapshot of the QEMU 1 input state. When set, drain merges FP/CSR/V
31	  // fields from the snapshot into the freshly drained GPRs+PC, avoiding
32	  // a per-field DM Abstract Command on every handoff.
33	  void set_passthrough_input(hybrid_state_v1 input)
34	  {
35	    passthrough_ = input;
36	  }
37	
38	  auto on_retire(uint64_t pc) -> std::optional<hybrid_state_v1>
39	  {
40	    const auto hit = trigger_.lookup(pc);
41	    // Only EXIT drains; entry is QEMU's job, vsim ignores ENTER.
42	    if (!hit || hit->kind != HYBRID_HANDOFF_EXIT)
43	      return std::nullopt;
44	    if (passthrough_)
45	      return drain_.drain_with_passthrough(*passthrough_);
46	    return drain_.drain();
47	  }
48	
49	private:
50	  Trigger trigger_;
51	  StateDrain drain_;
52	  std::optional<hybrid_state_v1> passthrough_;
53	};
